  1 | import { useCallback, useRef, useState, useEffect } from "react";
  2 | import { usePlayerWithAudio } from "./hooks/usePlayerWithAudio";
  3 | import { useMetadata } from "./hooks/useMetadata";
  4 | import { useTauri } from "./hooks/useTauri";
  5 | import { useAudioVisualizer } from "./hooks/useAudioVisualizer";
  6 | import {
  7 |   TitleBar,
  8 |   Playlist,
  9 |   PlayerControls,
 10 |   ProgressBar,
 11 |   StatusBar,
 12 |   DriveBrowser,
 13 |   AudioVisualizer,
 14 | } from "./components";
 15 | import type { Track } from "./types";
 16 | 
 17 | function App() {
 18 |   const {
 19 |     state,
 20 |     play,
 21 |     pause,
 22 |     next,
 23 |     prev,
 24 |     seek,
 25 |     setVolume,
 26 |     addTrack,
 27 |     toggleShuffle,
 28 |     reorderPlaylist,
 29 |     audioRef,
 30 |   } = usePlayerWithAudio([]);
 31 | 
 32 |   const { processFiles } = useMetadata();
 33 |   const {
 34 |     state: tauriState,
 35 |     openFilePicker,
 36 |     filePathToUrl,
 37 |     sendNotification,
 38 |     registerShortcuts,
 39 |   } = useTauri();
 40 | 
 41 |   const [isLoading, setIsLoading] = useState(false);
 42 |   const [showDrive, setShowDrive] = useState(false);
 43 | 
 44 |   const fileInputRef = useRef<HTMLInputElement>(null);
 45 | 
 46 |   // Registra atalhos de teclado (Media Session API + Tauri global shortcuts)
 47 |   useEffect(() => {
 48 |     const cleanup = registerShortcuts({
 49 |       MediaPlayPause: () => (state.isPlaying ? pause() : play()),
 50 |       MediaNextTrack: () => next(),
 51 |       MediaPrevTrack: () => prev(),
 52 |       MediaStop: () => pause(),
 53 |     });
 54 | 
 55 |     return () => {
 56 |       cleanup.then((fn) => fn());
 57 |     };
 58 |   }, [registerShortcuts, state.isPlaying, pause, play, next, prev]);
 59 | 
 60 |   // Media Session API (navegador)
 61 |   useEffect(() => {
 62 |     if (!("mediaSession" in navigator)) return;
 63 | 
 64 |     navigator.mediaSession.metadata = new MediaMetadata({
 65 |       title: state.currentTrack?.title ?? "Llama Player",
 66 |       artist: state.currentTrack?.artist ?? undefined,
 67 |       album: state.currentTrack?.album ?? undefined,
 68 |     });
 69 | 
 70 |     navigator.mediaSession.setActionHandler("play", () => play());
 71 |     navigator.mediaSession.setActionHandler("pause", () => pause());
 72 |     navigator.mediaSession.setActionHandler("nexttrack", () => next());
 73 |     navigator.mediaSession.setActionHandler("previoustrack", () => prev());
 74 |   }, [state.currentTrack, play, pause, next, prev]);
 75 | 
 76 |   // Notificação ao trocar de música
 77 |   useEffect(() => {
 78 |     if (state.currentTrack && state.isPlaying) {
 79 |       sendNotification(
 80 |         `▶ ${state.currentTrack.title}`,
 81 |         state.currentTrack.artist
 82 |           ? `Por ${state.currentTrack.artist}`
 83 |           : undefined
 84 |       );
 85 |     }
 86 |   }, [state.currentTrack?.id, state.isPlaying]); // eslint-disable-line react-hooks/exhaustive-deps
 87 | 
 88 |   const visualizer = useAudioVisualizer(audioRef, state.isPlaying);
 89 | 
 90 |   const handleSelectTrack = (track: Track) => {
 91 |     play(track);
 92 |   };
 93 | 
 94 |   const handleOpenFile = async () => {
 95 |     if (tauriState.isTauri) {
 96 |       // Usa file picker nativo do Tauri
 97 |       setIsLoading(true);
 98 |       try {
 99 |         const paths = await openFilePicker();
100 |         if (!paths || paths.length === 0) return;
101 | 
102 |         // Converte paths para File objects (via fetch do asset protocol)
103 |         const tracks: Track[] = [];
104 |         for (const path of paths) {
105 |           const url = await filePathToUrl(path);
106 |           const name = path.split(/[/\\]/).pop() || path;
107 |           tracks.push({
108 |             id: `local-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
109 |             title: name.replace(/\.[^/.]+$/, ""),
110 |             duration: 0,
111 |             src: url,
112 |           });
113 |         }
114 | 
115 |         for (const track of tracks) {
116 |           addTrack(track);
117 |         }
118 | 
119 |         if (!state.currentTrack && tracks.length > 0) {
120 |           play(tracks[0]);
121 |         }
122 |       } catch (err) {
123 |         console.error("[Llama Player] Erro ao abrir arquivos:", err);
124 |       } finally {
125 |         setIsLoading(false);
126 |       }
127 |     } else {
128 |       // Fallback: input file HTML
129 |       fileInputRef.current?.click();
130 |     }
131 |   };
132 | 
133 |   const handleFileChange = useCallback(
134 |     async (e: React.ChangeEvent<HTMLInputElement>) => {
135 |       const files = e.target.files;
136 |       if (!files || files.length === 0) return;
137 | 
138 |       setIsLoading(true);
139 | 
140 |       try {
141 |         const fileArray = Array.from(files);
142 |         const tracks = await processFiles(fileArray);
143 | 
144 |         for (const track of tracks) {
145 |           addTrack(track);
146 |         }
147 | 
148 |         // If nothing is playing, start with the first track
149 |         if (!state.currentTrack && tracks.length > 0) {
150 |           play(tracks[0]);
151 |         }
152 |       } catch (err) {
153 |         console.error("[Llama Player] Erro ao processar arquivos:", err);
154 |       } finally {
155 |         setIsLoading(false);
156 |       }
157 | 
158 |       // Reset input so the same file can be selected again
159 |       e.target.value = "";
160 |     },
161 |     [processFiles, addTrack, state.currentTrack, play]
162 |   );
163 | 
164 |   const handleDropFiles = useCallback(
165 |     async (files: FileList) => {
166 |       setIsLoading(true);
167 |       try {
168 |         const fileArray = Array.from(files);
169 |         const tracks = await processFiles(fileArray);
170 |         for (const track of tracks) {
171 |           addTrack(track);
172 |         }
173 |         if (!state.currentTrack && tracks.length > 0) {
174 |           play(tracks[0]);
175 |         }
176 |       } catch (err) {
177 |         console.error("[Llama Player] Erro ao processar arquivos arrastados:", err);
178 |       } finally {
179 |         setIsLoading(false);
180 |       }
181 |     },
182 |     [processFiles, addTrack, state.currentTrack, play]
183 |   );
184 | 
185 |   const handleAddDriveTracks = useCallback(
186 |     (tracks: Track[]) => {
187 |       for (const track of tracks) {
188 |         addTrack(track);
189 |       }
190 |       if (!state.currentTrack && tracks.length > 0) {
191 |         play(tracks[0]);
192 |       }
193 |     },
194 |     [addTrack, state.currentTrack, play]
195 |   );
196 | 
197 |   return (
198 |     <div className="app">
199 |       <TitleBar />
200 | 
201 |       <main className="main-content">
202 |         <div className="toolbar">
203 |           <button
204 |             className="toolbar-btn"
205 |             onClick={handleOpenFile}
206 |             disabled={isLoading}
207 |             title="Abrir arquivo de áudio local"
208 |           >
209 |             {isLoading ? "⏳ Lendo metadados..." : "📂 Arquivo local"}
210 |           </button>
211 |           <input
212 |             ref={fileInputRef}
213 |             type="file"
214 |             accept="audio/*"
215 |             multiple
216 |             style={{ display: "none" }}
217 |             onChange={handleFileChange}
218 |           />
219 |           <button
220 |             className={`toolbar-btn ${showDrive ? "toolbar-btn-active" : ""}`}
221 |             onClick={() => setShowDrive((v) => !v)}
222 |             title="Google Drive"
223 |           >
224 |             ☁️ Drive
225 |           </button>
226 |         </div>
227 | 
228 |         {showDrive && (
229 |           <DriveBrowser onAddTracks={handleAddDriveTracks} />
230 |         )}
231 | 
232 |         <Playlist
233 |           tracks={state.playlist}
234 |           currentTrackId={state.currentTrack?.id ?? null}
235 |           isPlaying={state.isPlaying}
236 |           onSelectTrack={handleSelectTrack}
237 |           onReorderPlaylist={reorderPlaylist}
238 |           onDropFiles={handleDropFiles}
239 |         />
240 | 
241 |         <PlayerControls
242 |           currentTrack={state.currentTrack}
243 |           isPlaying={state.isPlaying}
244 |           isShuffled={state.isShuffled}
245 |           onPlay={() => play()}
246 |           onPause={pause}
247 |           onNext={next}
248 |           onPrev={prev}
249 |           onToggleShuffle={toggleShuffle}
250 |         />
251 | 
252 |         <AudioVisualizer
253 |           frequencyData={visualizer.frequencyData}
254 |           waveformData={visualizer.waveformData}
255 |           isActive={visualizer.isActive}
256 |         />
257 | 
258 |         <ProgressBar
259 |           currentTime={state.currentTime}
260 |           duration={state.duration}
261 |           onSeek={seek}
262 |         />
263 |       </main>
264 | 
265 |       <StatusBar
266 |         isPlaying={state.isPlaying}
267 |         volume={state.volume}
268 |         onVolumeChange={setVolume}
269 |       />
270 |     </div>
271 |   );
272 | }
273 | 
274 | export default App;
